import java.io.*;
import java.util.*;

public class Main {
    static long POWER(long base, long expo) {
        long num = 1;
        long i = expo;
        while (i > 0) {
            num = num * base;
            i--;
        }
        return num;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long t = 1;
        while (t-- > 0) {
            long n = fs.nextLong();
            long m = fs.nextLong();
            long k = fs.nextLong();
            long[] a = new long[(int) n];
            for (int i = 0; i < n; i++)
                a[i] = fs.nextLong();
            Arrays.sort(a);
            if (m <= k) {
                System.out.print(0);
            } else {
                long sum = 0, i = n, devices = m, soc = k;
                while (sum < m && devices > soc && i >= 1) {
                    i--;
                    sum += a[(int) i];
                    devices -= a[(int) i];
                    soc--;
                }
                if (devices <= soc) {
                    System.out.print(n - i);
                } else {
                    i = n;
                    long used = 0, ss = 0, j = 0;
                    while (i >= 1 && ss < m) {
                        i--;
                        if (used >= k * j && j >= 1)
                            ss--;
                        ss += a[(int) i];
                        used++;
                        if (used % k == 0 && used != 0)
                            j++;
                    }
                    if (ss >= m)
                        System.out.print(used);
                    else
                        System.out.print(-1);
                }
            }
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
}

